/** Fixed public endpoint/literal parsers; never evaluates remote scripts.
 * Endpoint references: Keiyoushi GoDa, Comicabc and MangaKatana (Apache-2.0). */
final class SourceExtra {
    static boolean handles(String t){return Arrays.asList("goda","comicabc","mangakatana").contains(t);}
    static final String API="https://api-get-v3.mgsearcher.com";
    static final class A {Map<String,String> attrs;Set<String> context=new HashSet<>();StringBuilder body=new StringBuilder(),headline=new StringBuilder(),caption=new StringBuilder();String cover="";String title(){String s=SourceHtml.text(body.toString());return s.isEmpty()?attrs.getOrDefault("title",""):s;}}
    static final class Tag {String name;Set<String> classes=new HashSet<>();Tag(String n,Map<String,String> attrs){name=n;classes.addAll(Arrays.asList(attrs.getOrDefault("class","").split("\\s+")));classes.add(attrs.getOrDefault("id",""));}}
    static List<A> anchors(String html){
        List<A> out=new ArrayList<>();List<Tag> stack=new ArrayList<>();A active=null;Matcher tokens=Pattern.compile("(?s)<[^>]*>|[^<]+").matcher(html);
        while(tokens.find()){String t=tokens.group();if(!t.startsWith("<")){if(active!=null){active.body.append(t).append(' ');for(Tag e:stack){if(e.name.equals("h3"))active.headline.append(t);if(e.name.equals("li")&&e.classes.contains("nowraphide"))active.caption.append(t);}}continue;}
            Matcher tag=Pattern.compile("^<\\s*(/?)\\s*([\\w]+)").matcher(t);if(!tag.find())continue;String name=tag.group(2).toLowerCase(Locale.ROOT);
            if(!tag.group(1).isEmpty()){if(name.equals("a")&&active!=null){out.add(active);active=null;}for(int i=stack.size()-1;i>=0;i--)if(stack.get(i).name.equals(name)){while(stack.size()>i)stack.remove(stack.size()-1);break;}continue;}
            Map<String,String> attrs=SourceHtml.attrs(t);if(name.equals("a")){if(active!=null)out.add(active);active=new A();active.attrs=attrs;for(Tag e:stack)active.context.addAll(e.classes);}
            if(name.equals("img")&&active!=null)active.cover=attrs.getOrDefault("data-src",attrs.getOrDefault("data-original",attrs.getOrDefault("src","")));
            if(!Arrays.asList("img","br","hr","input","meta","link","source","wbr","area","embed").contains(name)&&!t.endsWith("/>"))stack.add(new Tag(name,attrs));
        }return out;
    }
    static String get(JSONObject s,String path)throws Exception{return SourceHtml.get(s,path);}
    static Online.Result search(JSONObject s,String term,int page)throws Exception{
        String type=s.getString("type"),path=type.equals("goda")?(term.isEmpty()?"/hots/page/"+page:"/s/"+Online.enc(term).replace("+","%20")+"?page="+page):type.equals("comicabc")?(term.isEmpty()?"/comic/h-"+page+".html":"/member/search.aspx?key="+Online.enc(term)+"&page="+page):(term.isEmpty()?"/manga/page/"+page:"/page/"+page+"?search="+Online.enc(term)+"&search_by=book_name");
        Map<String,JSONObject> rows=new LinkedHashMap<>();Set<String> blocked=new HashSet<>();Online.Result result=new Online.Result();
        for(A a:anchors(get(s,path))){String id=SourceHtml.local(s,a.attrs.getOrDefault("href","")),title=a.title(),classes=a.attrs.getOrDefault("class","");boolean match=type.equals("goda")?id.matches("/manga/[^/]+/?")&&a.context.contains("cardlist"):type.equals("comicabc")?id.matches("/html/[0-9]+\\.html")&&Arrays.asList(classes.split("\\s+")).contains("comicpic_col6"):id.matches("/manga/[^/]+\\.[0-9]+")&&a.context.contains("book_list");
            if(match){if(type.equals("comicabc")&&(title.contains("登入觀看")||title.contains("登录观看"))){blocked.add(id);continue;}String caption=SourceHtml.text((type.equals("goda")?a.headline:a.caption).toString());if(!caption.isEmpty()&&!type.equals("mangakatana"))title=caption;if(type.equals("goda"))title=title.replaceAll("(?:連載|完結)$","").trim();JSONObject row=rows.get(id);if(row==null){row=Online.item(id,"","");rows.put(id,row);}if(!title.isEmpty())row.put("title",title);if(!a.cover.isEmpty()){String cover=new URL(Online.checked(Online.base(s)),a.cover).toString();if(type.equals("goda")){String q=new URL(cover).getQuery();if(q!=null)for(String kv:q.split("&"))if(kv.startsWith("url="))cover=URLDecoder.decode(kv.substring(4),"UTF-8");}row.put("cover",cover);}}
            String label=a.attrs.getOrDefault("aria-label","");if(type.equals("goda")&&Arrays.asList("下一頁","下一页","NEXT").contains(label)&&!a.attrs.getOrDefault("aria-disabled","").equals("true")||type.equals("comicabc")&&(title.contains("下一頁")||title.contains("下一页")||classes.contains("mdi-skip-next"))||type.equals("mangakatana")&&classes.contains("next")&&classes.contains("page-numbers"))result.more=true;
        }for(Map.Entry<String,JSONObject> row:rows.entrySet())if(!blocked.contains(row.getKey())&&!row.getValue().optString("title").isEmpty())result.books.put(row.getValue());return result;
    }
    static JSONArray chapters(JSONObject s,String book)throws Exception{
        String type=s.getString("type");JSONArray out=new JSONArray();
        if(type.equals("goda")){if(!book.matches("/manga/[^/]+/?"))throw new IOException("作品地址无效");Matcher m=Pattern.compile("data-mid=['\"]([0-9]+)['\"]").matcher(get(s,book));if(!m.find())throw new IOException("作品已下架或没有公开章节");String mid=m.group(1);JSONArray rows=((JSONObject)Online.json(s,API+"/api/manga/get?mid="+mid+"&mode=all")).optJSONObject("data").optJSONArray("chapters");List<JSONObject> sorted=new ArrayList<>();if(rows!=null)for(int i=0;i<rows.length();i++)sorted.add(rows.getJSONObject(i));sorted.sort((a,b)->Double.compare(a.optJSONObject("attributes").optDouble("order",0),b.optJSONObject("attributes").optDouble("order",0)));for(JSONObject c:sorted)if(c.optString("id").matches("[0-9]+"))out.put(new JSONObject().put("id",mid+"/"+c.optString("id")).put("title",c.getJSONObject("attributes").optString("title","未命名章节")));}
        else{if(!book.matches(type.equals("comicabc")?"/html/[0-9]+\\.html":"/manga/[^/]+\\.[0-9]+"))throw new IOException("作品地址无效");Map<String,JSONObject> rows=new LinkedHashMap<>();String bid=book.replaceAll("[^0-9]","");for(A a:anchors(get(s,book))){String id,title=a.title();if(type.equals("comicabc")){Matcher m=Pattern.compile("cview\\(['\"]"+bid+"-([0-9]+[a-z]?)\\.html").matcher(a.attrs.getOrDefault("onclick",""));if(!m.find())continue;id="https://articles.onemoreplace.tw/online/new-"+bid+".html?ch="+m.group(1);}else{id=SourceHtml.local(s,a.attrs.getOrDefault("href",""));if(!id.matches(Pattern.quote(book)+"/c[0-9.]+(?:x[0-9]+)?"))continue;}if(!rows.containsKey(id))rows.put(id,new JSONObject().put("id",id).put("title",title.isEmpty()?"未命名章节":title));}List<JSONObject> sorted=new ArrayList<>(rows.values());if(type.equals("comicabc"))sorted.sort((a,b)->{double x=Double.parseDouble(a.optString("id").replaceAll(".*ch=([0-9]+).*","$1")),y=Double.parseDouble(b.optString("id").replaceAll(".*ch=([0-9]+).*","$1"));return x==y?a.optString("id").compareTo(b.optString("id")):Double.compare(x,y);});else Collections.reverse(sorted);for(JSONObject c:sorted)out.put(c);}
        if(out.length()==0)throw new IOException("未找到公开章节，可能需要登录或作品已下架");return out;
    }
    static JSONArray decodeGoda(String encoded)throws Exception{
        if(encoded.length()>4*1024*1024||!encoded.startsWith("J7r")||!encoded.endsWith("nQ"))throw new IOException("图片清单格式无效");String body=encoded.substring(3,encoded.length()-2);int n=body.length()-5,a=n/3,b=(n-a)/2,c=n-a-b;if(n<=0||!body.substring(b,b+2).equals("kD")||!body.substring(b+2+c,b+2+c+3).equals("W4s"))throw new IOException("图片清单标记无效");String reordered=body.substring(b+2+c+3)+body.substring(0,b)+body.substring(b+2,b+2+c);StringBuilder value=new StringBuilder();for(int i=0;i<reordered.length();i+=7){String chunk=reordered.substring(i,Math.min(i+7,reordered.length()));value.append(i/7%2==1?new StringBuilder(chunk).reverse():chunk);}String custom="_-9876543210abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ",standard="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";StringBuilder base64=new StringBuilder();for(int i=0;i<value.length();i++){int ix=custom.indexOf(value.charAt(i));if(ix<0)throw new IOException("图片清单字符无效");base64.append(standard.charAt(ix));}JSONArray rows=new JSONArray(new String(java.util.Base64.getUrlDecoder().decode(base64.toString()),"UTF-8"));if(rows.length()==0||rows.length()>10000)throw new IOException("图片清单大小无效");List<JSONObject> sorted=new ArrayList<>();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);String url=row.getString("url");if(!url.startsWith("/")||url.startsWith("//"))throw new IOException("图片路径无效");sorted.add(row);}sorted.sort((x,y)->Integer.compare(x.optInt("order"),y.optInt("order")));JSONArray out=new JSONArray();for(JSONObject row:sorted)out.put(row);return out;
    }
    static int number(String value)throws Exception{String alpha="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";if(value.length()!=2||alpha.indexOf(value.charAt(0))<0||alpha.indexOf(value.charAt(1))<0)throw new IOException("图片编号无效");return value.charAt(0)=='Z'?8000+alpha.indexOf(value.charAt(1)):alpha.indexOf(value.charAt(0))*52+alpha.indexOf(value.charAt(1));}
    static String tail(String big,int n)throws Exception{int start=big.length()-47-n*6;if(start<0)throw new IOException("图片主机记录不完整");StringBuilder out=new StringBuilder();for(int i=start;i<start+6;i+=2){int v=Integer.parseInt(big.substring(i,i+2),16);if(v>127)throw new IOException("图片主机无效");out.append((char)v);}return out.toString();}
    static List<String> comicImages(String script,String chapter)throws Exception{
        Matcher values=Pattern.compile("var\\s+\\w+\\s*=\\s*('(?:\\\\.|[^'\\\\])*')").matcher(script);String big="";while(values.find()){String v=SourceHtml.literal(values.group(1));if(v.length()>big.length())big=v;}Matcher count=Pattern.compile("for\\s*\\(var\\s+i=0;i<([0-9]+);i\\+\\+\\)").matcher(script),book=Pattern.compile("var\\s+ti=([0-9]+)").matcher(script);if(big.length()<1000||big.length()>4*1024*1024||!count.find()||!book.find()||!Pattern.compile("\\.length-47-\\w+\\*6").matcher(script).find())throw new IOException("图片记录格式已变化");int size=Integer.parseInt(count.group(1));if(size>10000||!chapter.matches("[0-9]+[a-z]?"))throw new IOException("章节编号无效");int target=Integer.parseInt(chapter.replaceAll("[a-z]$",""));String suffix=chapter.replaceAll("^[0-9]+","");for(int i=0;i<size;i++){if((i+1)*47>big.length())throw new IOException("图片记录不完整");String record=big.substring(i*47,(i+1)*47),part=record.substring(46);int cid=number(record.substring(42,44));if(cid!=target||!suffix.isEmpty()&&!suffix.equals(part))continue;int pages=number(record.substring(0,2));String folder=String.valueOf(number(record.substring(44,46))),cipher=record.substring(2,42);if(pages<1||pages>10000||folder.length()<2)throw new IOException("图片记录范围无效");String host=tail(big,4)+folder.charAt(0)+".8"+tail(big,3)+tail(big,2)+tail(big,3);if(!host.endsWith(".8comic.com")||!host.matches("[A-Za-z0-9.-]+"))throw new IOException("图片主机无效");String prefix="https://"+host+"/"+folder.charAt(1)+"/"+book.group(1)+"/"+cid+(part.equals("0")?"":part)+"/";List<String> out=new ArrayList<>();for(int j=1;j<=pages;j++){int start=((j-1)/10)%10+((j-1)%10)*3;out.add(prefix+String.format(Locale.ROOT,"%03d",j)+"_"+cipher.substring(start,start+3)+"."+tail(big,1));}return out;}throw new IOException("该章节没有公开图片记录");
    }
    static List<String> pages(JSONObject s,JSONObject chapter)throws Exception{
        String type=s.getString("type"),id=chapter.getString("id");List<String> out=new ArrayList<>();
        if(type.equals("goda")){if(!id.matches("[0-9]+/[0-9]+"))throw new IOException("章节地址无效");String[] ids=id.split("/");JSONObject data=(JSONObject)Online.json(s,API+"/api/v2/chapter/getinfo?m="+ids[0]+"&c="+ids[1]);JSONArray rows=decodeGoda(data.getJSONObject("data").getJSONObject("info").getJSONObject("images").getString("images"));for(int i=0;i<rows.length();i++)out.add("https://c-nd2-1.6wm.top"+rows.getJSONObject(i).getString("url"));}
        else if(type.equals("comicabc")){if(!id.matches("https://articles\\.onemoreplace\\.tw/online/new-[0-9]+\\.html\\?ch=[0-9]+[a-z]?"))throw new IOException("章节地址无效");String raw=get(s,id);Matcher scripts=Pattern.compile("(?is)<script\\b[^>]*>(.*?)</script>").matcher(raw);while(scripts.find())if(scripts.group(1).contains("$(\"#comics-pics\").html(xx)"))return comicImages(scripts.group(1),id.substring(id.indexOf("?ch=")+4));throw new IOException("未找到公开图片记录");}
        else{if(!id.matches("/manga/[^/]+\\.[0-9]+/c[0-9.]+(?:x[0-9]+)?"))throw new IOException("章节地址无效");String raw=get(s,id);Matcher name=Pattern.compile("data-src['\"],\\s*(\\w+)").matcher(raw);if(!name.find())throw new IOException("未找到公开图片清单");Matcher list=Pattern.compile("var\\s+"+Pattern.quote(name.group(1))+"\\s*=\\s*\\[([^\\[]*)\\]").matcher(raw);if(!list.find()||list.group(1).length()>4*1024*1024)throw new IOException("图片清单无效");Matcher literal=Pattern.compile("'(?:\\\\.|[^'\\\\])*'").matcher(list.group(1));while(literal.find())out.add(SourceHtml.literal(literal.group()));}
        return out;
    }
}
